create function world_knowledge_private.attribute_value_valid_v5(p_registry_version text,p_attribute_key text,p_state text,p_value jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare a jsonb; o jsonb; t jsonb; ids text[]:='{}'; offer_ids text[]:='{}'; amount numeric;
begin
 if p_registry_version<>'backyrd.world-knowledge.registry@2.3' then return false; end if;
 if p_state='UNKNOWN' then return p_value is null or p_value='null'::jsonb; end if;
 if p_attribute_key='description.discovery_source' then return p_state='KNOWN_VALUE' and jsonb_typeof(p_value)='string' and length(trim(p_value#>>'{}')) between 1 and 12000; end if;
 if p_attribute_key<>'discovery.profile' then return world_knowledge_private.attribute_value_valid_v4('backyrd.world-knowledge.registry@2.2',p_attribute_key,p_state,p_value); end if;
 if p_state<>'KNOWN_VALUE' or jsonb_typeof(p_value)<>'object' or not(p_value?'contractVersion' and p_value?'description' and p_value?'offerings' and p_value?'assertions' and p_value?'reviewed') or (select count(*) from jsonb_object_keys(p_value))<>5 or p_value->>'contractVersion'<>'backyrd.world-knowledge.discovery-profile@1.0' or p_value->'reviewed'<>'true'::jsonb or jsonb_typeof(p_value->'description')<>'string' or length(trim(p_value->>'description')) not between 1 and 12000 or jsonb_typeof(p_value->'offerings')<>'array' or jsonb_typeof(p_value->'assertions')<>'array' or jsonb_array_length(p_value->'offerings')>30 or jsonb_array_length(p_value->'assertions')>60 then return false; end if;
 for o in select value from jsonb_array_elements(p_value->'offerings') loop
  if jsonb_typeof(o)<>'object' or not(o?'id' and o?'name' and o?'description' and o?'price') or (select count(*) from jsonb_object_keys(o))<>4 or jsonb_typeof(o->'id')<>'string' or o->>'id' !~ '^[a-zA-Z0-9_-]{1,60}$' or o->>'id'=any(offer_ids) or jsonb_typeof(o->'name')<>'string' or length(trim(o->>'name')) not between 1 and 160 or jsonb_typeof(o->'description')<>'string' or length(trim(o->>'description')) not between 1 and 1000 then return false; end if;
  offer_ids:=array_append(offer_ids,o->>'id');
  if o->'price'<>'null'::jsonb then
   a:=o->'price';if jsonb_typeof(a)<>'object' or not(a?'currency' and a?'min' and a?'max' and a?'basis' and a?'mandatoryFeesIncluded') or (select count(*) from jsonb_object_keys(a))<>5 or a->>'currency' !~ '^[A-Z]{3}$' or a->>'basis' not in ('PER_PERSON','PER_GROUP') or jsonb_typeof(a->'mandatoryFeesIncluded') not in ('boolean','null') or jsonb_typeof(a->'min')<>'number' or jsonb_typeof(a->'max')<>'number' or (a->>'min')::numeric<0 or (a->>'max')::numeric>100000 or (a->>'min')::numeric>(a->>'max')::numeric or (a->>'min')::numeric*100<>trunc((a->>'min')::numeric*100) or (a->>'max')::numeric*100<>trunc((a->>'max')::numeric*100) then return false;end if;
  end if;
 end loop;
 for a in select value from jsonb_array_elements(p_value->'assertions') loop
  if jsonb_typeof(a)<>'object' or not(a?'id' and a?'kind' and a?'concepts' and a?'offeringId' and a?'state' and a?'evidence' and a?'validFrom' and a?'validUntil' and a?'conditions') or (select count(*) from jsonb_object_keys(a))<>9 or a->>'id' !~ '^[a-zA-Z0-9_-]{1,60}$' or a->>'id'=any(ids) or a->>'kind' not in ('VISIT','OFFERING','ATMOSPHERE','SETTING','FEATURE') or a->>'state' not in ('PRESENT','ABSENT') or jsonb_typeof(a->'concepts')<>'array' or jsonb_array_length(a->'concepts') not between 1 and 8 or jsonb_typeof(a->'evidence')<>'string' or length(a->>'evidence') not between 1 and 1000 or strpos(p_value->>'description',a->>'evidence')=0 then return false;end if;
  ids:=array_append(ids,a->>'id');
  if a->'offeringId'<>'null'::jsonb and (jsonb_typeof(a->'offeringId')<>'string' or not(a->>'offeringId'=any(offer_ids))) or a->>'kind'='OFFERING' and a->>'state'='PRESENT' and a->'offeringId'='null'::jsonb then return false;end if;
  for t in select value from jsonb_array_elements(a->'concepts') loop if jsonb_typeof(t)<>'string' or length(trim(t#>>'{}')) not between 1 and 160 then return false;end if;end loop;
  if (select count(distinct lower(regexp_replace(normalize(value,NFKD),U&'[\0300-\036f]','','g'))) from jsonb_array_elements_text(a->'concepts'))<>jsonb_array_length(a->'concepts') then return false;end if;
  if a->'conditions'<>'null'::jsonb and (jsonb_typeof(a->'conditions')<>'string' or length(trim(a->>'conditions')) not between 1 and 500) then return false;end if;
  if a->'validFrom'<>'null'::jsonb then perform (a->>'validFrom')::timestamptz;end if;
  if a->'validUntil'<>'null'::jsonb then perform (a->>'validUntil')::timestamptz;end if;
  if a->'validFrom'<>'null'::jsonb and a->'validUntil'<>'null'::jsonb and (a->>'validFrom')::timestamptz>(a->>'validUntil')::timestamptz then return false;end if;
 end loop;
 return true;
exception when others then return false;
end $$;
revoke all on function world_knowledge_private.attribute_value_valid_v5(text,text,text,jsonb) from public,anon,authenticated,service_role;
create function world_knowledge_private.validate_claim_insert_v5() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.registry_version='backyrd.world-knowledge.registry@2.3' and not world_knowledge_private.attribute_value_valid_v5(new.registry_version,new.attribute_key,new.knowledge_state,new.value) then raise exception 'invalid_attribute_value' using errcode='22023';end if;
 return new;
end $$;
revoke all on function world_knowledge_private.validate_claim_insert_v5() from public,anon,authenticated,service_role;
create trigger world_00_validate_claim_insert_v5 before insert on world_knowledge_private.claims for each row execute function world_knowledge_private.validate_claim_insert_v5();

create or replace function world_knowledge_private.submit_authoritative_claim_v5(
  p_actor_type text,p_spot_id uuid,p_attribute_key text,p_knowledge_state text,
  p_value jsonb,p_observed_at timestamptz,p_valid_from timestamptz,
  p_valid_until timestamptz,p_visibility text,p_supersedes_claim_id uuid,
  p_idempotency_key text
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
  actor_id uuid:=auth.uid(); entitlement_scope text; binding_id uuid; source_id uuid;
  v_claim_id uuid; content_hash text; method text; authority text;
  prior world_knowledge_private.claims%rowtype; shadow_hold boolean;
  checked_at_value timestamptz; freshness_ref text; reason_values text[];
  verification_hash text;
begin
  if actor_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_actor_type='VERIFIED_OWNER' then
    if not exists(select 1 from public.spots where id=p_spot_id and owner_id=actor_id) then raise exception 'spot_owner_required' using errcode='42501'; end if;
    entitlement_scope:=case when exists(
      select 1 from public.backyrd_spot_owner_intelligence_entitlements_v1
      where spot_id=p_spot_id and owner_id=actor_id and tier='PREMIUM'
        and valid_from<=pg_catalog.clock_timestamp()
        and (valid_until is null or valid_until>pg_catalog.clock_timestamp())
    ) then 'OWNER_PRO' else 'OWNER_BASIC' end;
    method:='OWNER_CONFIRMED'; authority:='SERVER_BOUND_OWNER_WRITE';
  elsif p_actor_type='ADMIN' then
    if not public.is_admin_v1(actor_id) then raise exception 'admin_required' using errcode='42501'; end if;
    entitlement_scope:='ADMIN'; method:='ADMIN_CONFIRMED'; authority:='SERVER_BOUND_ADMIN_WRITE';
  else raise exception 'invalid_authoritative_actor' using errcode='22023';
  end if;
  if not exists(
    select 1 from world_knowledge_private.entitlement_attribute_rules
    where policy_version='backyrd.world-knowledge.entitlement-policy@4d.1'
      and actor_scope=entitlement_scope and attribute_key=p_attribute_key
  ) then raise exception 'attribute_entitlement_denied' using errcode='42501'; end if;
  if p_observed_at is null or p_observed_at>pg_catalog.clock_timestamp()+interval '60 seconds' then raise exception 'invalid_observed_at' using errcode='22023'; end if;
  if p_valid_until is not null and p_valid_from is not null and p_valid_until<p_valid_from then raise exception 'invalid_validity_window' using errcode='22023'; end if;
  if p_attribute_key='state.current' and p_valid_until is null then raise exception 'current_state_valid_until_required' using errcode='22023'; end if;
  if p_visibility not in ('PUBLIC','INTERNAL') or length(trim(coalesce(p_idempotency_key,''))) not between 1 and 180 then raise exception 'invalid_claim_metadata' using errcode='22023'; end if;
  if p_attribute_key='discovery.profile' and p_knowledge_state='KNOWN_VALUE' and not exists(
    select 1 from (select * from world_knowledge_private.claims where spot_id=p_spot_id and attribute_key='description.discovery_source' order by last_changed_at desc,id desc limit 1) source
    where source.visibility='PUBLIC' and source.knowledge_state='KNOWN_VALUE' and source.value=to_jsonb(p_value->>'description') and source.stance='SUPPORTS'
  ) then raise exception 'discovery_source_changed_or_not_public' using errcode='22023';end if;
  if not world_knowledge_private.attribute_value_valid_v5('backyrd.world-knowledge.registry@2.3',p_attribute_key,p_knowledge_state,p_value) then raise exception 'invalid_attribute_value' using errcode='22023'; end if;
  if p_supersedes_claim_id is not null then
    select * into prior from world_knowledge_private.claims where id=p_supersedes_claim_id;
    if not found or prior.spot_id<>p_spot_id or prior.attribute_key<>p_attribute_key then raise exception 'invalid_supersedes_claim' using errcode='22023'; end if;
  end if;
  binding_id:=world_knowledge_private.get_actor_binding_v1(actor_id,p_actor_type);
  content_hash:=encode(extensions.digest(pg_catalog.convert_to(jsonb_build_object(
    'spotId',p_spot_id,'key',p_attribute_key,'state',p_knowledge_state,'value',p_value,
    'actorBinding',binding_id,'observedAt',p_observed_at,'validFrom',p_valid_from,
    'validUntil',p_valid_until,'supersedes',p_supersedes_claim_id,
    'registry','backyrd.world-knowledge.registry@2.3',
    'policy','backyrd.world-knowledge.source-policy@4d.1'
  )::text,'UTF8'),'sha256'),'hex');
  select id into v_claim_id from world_knowledge_private.claims
  where actor_binding_id=binding_id and idempotency_key=p_idempotency_key;
  if found then
    if (select c.content_hash from world_knowledge_private.claims c where c.id=v_claim_id)<>content_hash then raise exception 'claim_idempotency_conflict' using errcode='23505'; end if;
    return jsonb_build_object('claimId',v_claim_id,'created',false);
  end if;
  insert into world_knowledge_private.source_references(spot_id,source_type,visibility,source_hash)
  values(
    p_spot_id,case when p_actor_type='ADMIN' then 'ADMIN_OBSERVATION' else 'OWNER_ASSERTION' end,'INTERNAL',
    encode(extensions.digest(pg_catalog.convert_to(binding_id::text||':'||p_idempotency_key,'UTF8'),'sha256'),'hex')
  ) returning id into source_id;
  shadow_hold:=world_knowledge_private.text_requires_shadow_v1(p_attribute_key,p_value);
  insert into world_knowledge_private.claims(
    idempotency_key,spot_id,registry_version,policy_version,attribute_key,knowledge_state,value,
    actor_binding_id,actor_type,source_reference_id,source_type,observed_at,valid_from,
    valid_until,last_changed_at,stance,visibility,supersedes_claim_id,content_hash
  ) values (
    p_idempotency_key,p_spot_id,'backyrd.world-knowledge.registry@2.3',
    'backyrd.world-knowledge.source-policy@4d.1',p_attribute_key,p_knowledge_state,p_value,
    binding_id,p_actor_type,source_id,case when p_actor_type='ADMIN' then 'ADMIN_OBSERVATION' else 'OWNER_ASSERTION' end,
    p_observed_at,p_valid_from,p_valid_until,pg_catalog.clock_timestamp(),'SUPPORTS',
    case when shadow_hold then 'SHADOW_HELD' else p_visibility end,p_supersedes_claim_id,content_hash
  ) returning id into v_claim_id;
  checked_at_value:=pg_catalog.clock_timestamp();
  freshness_ref:=case
    when p_attribute_key='state.current' then 'freshness:current-state:explicit-valid-until'
    when p_attribute_key in ('hours.special','hours.kitchen_special') then 'freshness:special-hours:date-bound'
    when p_attribute_key like 'hours.%' then 'freshness:opening-hours:confirmed-until-changed'
    else 'freshness:durable-until-contradicted'
  end;
  reason_values:=array['SERVER_ACTOR_SCOPE_AND_PAYLOAD_CONFIRMED'];
  verification_hash:=encode(extensions.digest(pg_catalog.convert_to(jsonb_build_object(
    'claimId',v_claim_id,'claimHash',content_hash,'spotId',p_spot_id,'attributeKey',p_attribute_key,
    'scope','SPOT','policyVersion','backyrd.world-knowledge.source-policy@4d.1','method',method,
    'authority',authority,'verifierBinding',binding_id,'result','VERIFIED',
    'checkedAt',checked_at_value,'reverificationPolicyRef',freshness_ref,'reasonCodes',to_jsonb(reason_values)
  )::text,'UTF8'),'sha256'),'hex');
  insert into world_knowledge_private.verification_records(
    claim_id,claim_hash,spot_id,attribute_key,scope,policy_version,verification_method,
    execution_authority,verifier_binding_id,result,checked_at,reverification_policy_ref,
    reason_codes,result_hash
  ) values (
    v_claim_id,content_hash,p_spot_id,p_attribute_key,'SPOT',
    'backyrd.world-knowledge.source-policy@4d.1',method,authority,binding_id,'VERIFIED',
    checked_at_value,freshness_ref,reason_values,verification_hash
  );
  if shadow_hold then
    insert into world_knowledge_private.review_work_items(
      spot_id,work_class,priority,attribute_key,candidate_payload,reason_codes
    ) values (p_spot_id,'CONTENT_SAFETY','HIGH',p_attribute_key,jsonb_build_object('claimId',v_claim_id),array['NEW_TEXT_SHADOW_HELD']);
  end if;
  if exists(
    select 1 from world_knowledge_private.claims c
    join world_knowledge_private.verification_records v on v.claim_id=c.id and v.result='VERIFIED'
    where c.spot_id=p_spot_id and c.attribute_key=p_attribute_key and c.id<>v_claim_id
      and c.value is distinct from p_value
      and c.observed_at between p_observed_at-interval '5 minutes' and p_observed_at+interval '5 minutes'
  ) then
    insert into world_knowledge_private.review_work_items(
      spot_id,work_class,priority,attribute_key,candidate_payload,reason_codes
    ) values (p_spot_id,'AUTHORITY_CONFLICT','HIGH',p_attribute_key,jsonb_build_object('claimId',v_claim_id),array['CONCURRENT_AUTHORITATIVE_CONFLICT']);
  end if;
  return jsonb_build_object('claimId',v_claim_id,'created',true,'verificationMethod',method,'visibility',case when shadow_hold then 'SHADOW_HELD' else p_visibility end);
end $$;

create or replace function world_knowledge_private.resolution_input_components_v5(p_spot_id uuid,p_as_of timestamptz,p_ledger_cutoff_at timestamptz)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare registry_record world_knowledge_private.registry_releases%rowtype; policy_record world_knowledge_private.source_policy_releases%rowtype; attribute_policy jsonb; attribute_policy_hash text;
begin
  select * into strict registry_record from world_knowledge_private.registry_releases where registry_version='backyrd.world-knowledge.registry@2.3';
  select * into strict policy_record from world_knowledge_private.source_policy_releases where policy_version='backyrd.world-knowledge.source-policy@4d.1' and state='ACCEPTED' and registry_version=registry_record.registry_version and registry_hash=registry_record.registry_hash;
  select coalesce(jsonb_agg(jsonb_build_object(
    'attributeKey',r.attribute_key,'allowedSourceTypes',to_jsonb(r.allowed_source_types),'allowedActorTypes',to_jsonb(r.allowed_actor_types),
    'sourceReferenceRequirement',r.source_reference_requirement,'selfAssertionAllowed',r.self_assertion_allowed,
    'verificationProcessIds',to_jsonb(r.verification_process_ids),'freshnessPolicyRef',r.freshness_policy_ref,
    'allowedUseCases',to_jsonb(r.allowed_use_cases)
  ) order by r.attribute_key),'[]'::jsonb) into attribute_policy
  from world_knowledge_private.source_policy_attribute_rules r where r.policy_version=policy_record.policy_version;
  attribute_policy_hash:=encode(extensions.digest(pg_catalog.convert_to(attribute_policy::text,'UTF8'),'sha256'),'hex');
  return jsonb_build_object(
    'spotId',p_spot_id,'asOf',p_as_of,
    'claims',(select coalesce(jsonb_agg(jsonb_build_object('claimId',c.id,'claimHash',c.content_hash) order by c.id),'[]'::jsonb) from world_knowledge_private.claims c where c.spot_id=p_spot_id and c.observed_at<=p_as_of and c.created_at<=p_ledger_cutoff_at),
    'verifications',(select coalesce(jsonb_agg(jsonb_build_object('verificationId',v.id,'verificationHash',v.result_hash) order by v.id),'[]'::jsonb) from world_knowledge_private.verification_records v join world_knowledge_private.claims c on c.id=v.claim_id where c.spot_id=p_spot_id and c.created_at<=p_ledger_cutoff_at and v.created_at<=p_ledger_cutoff_at and v.checked_at<=p_as_of),
    'registry',jsonb_build_object('version',registry_record.registry_version,'registryHash',registry_record.registry_hash,'releaseHash',registry_record.release_hash),
    'sourcePolicy',jsonb_build_object('version',policy_record.policy_version,'releaseHash',policy_record.policy_hash,'attributePolicyHash',attribute_policy_hash),
    'resolver',jsonb_build_object('contract','backyrd.world-knowledge.shadow-resolver@1.0','version','2.3.0'),
    'conflictPolicyRef','conflict:latest-authoritative-change-review@3b.1',
    'freshnessPolicyRef','freshness:attribute-policy-bound@3b.1',
    'shadowPolicyRef','shadow:excluded-inputs-bind-manifest@3b.1'
  );
exception when no_data_found then raise exception 'resolver_release_not_accepted' using errcode='22023';
end $$;

create or replace function world_knowledge_private.authoring_actor_v1(p_spot_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor_id uuid:=auth.uid(); actor_role text; entitlement text; allowed_keys jsonb;
begin
  if not world_knowledge_private.founder_authoring_enabled_v1() then raise exception 'founder_authoring_environment_disabled' using errcode='42501'; end if;
  if actor_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if public.is_admin_v1(actor_id) then actor_role:='ADMIN'; entitlement:='ADMIN';
  elsif p_spot_id is not null and exists(select 1 from public.spots s where s.id=p_spot_id and s.owner_id=actor_id) then
    actor_role:='VERIFIED_OWNER';
    entitlement:=case when exists(
      select 1 from public.backyrd_spot_owner_intelligence_entitlements_v1 e
      where e.spot_id=p_spot_id and e.owner_id=actor_id and e.tier='PREMIUM'
        and e.valid_from<=pg_catalog.clock_timestamp()
        and (e.valid_until is null or e.valid_until>pg_catalog.clock_timestamp())
    ) then 'OWNER_PRO' else 'OWNER_BASIC' end;
  else raise exception 'world_authoring_scope_denied' using errcode='42501'; end if;
  select coalesce(jsonb_agg(r.attribute_key order by r.attribute_key),'[]'::jsonb) into allowed_keys
  from world_knowledge_private.entitlement_attribute_rules r
  where r.policy_version='backyrd.world-knowledge.entitlement-policy@4d.1' and r.actor_scope=entitlement;
  return jsonb_build_object('role',actor_role,'entitlement',entitlement,'allowedAttributeKeys',allowed_keys);
end $$;

create or replace function public.world_owner_submit_claim_v1(
  p_spot_id uuid,p_attribute_key text,p_knowledge_state text,p_value jsonb,
  p_observed_at timestamptz,p_valid_from timestamptz default null,
  p_valid_until timestamptz default null,p_visibility text default 'PUBLIC',
  p_supersedes_claim_id uuid default null,p_idempotency_key text default null
) returns jsonb language sql security definer set search_path='' as $$
  select world_knowledge_private.submit_authoritative_claim_v5(
    'VERIFIED_OWNER',p_spot_id,p_attribute_key,p_knowledge_state,p_value,p_observed_at,
    p_valid_from,p_valid_until,p_visibility,p_supersedes_claim_id,p_idempotency_key
  );
$$;

create or replace function public.world_admin_submit_claim_v1(
  p_spot_id uuid,p_attribute_key text,p_knowledge_state text,p_value jsonb,
  p_observed_at timestamptz,p_valid_from timestamptz default null,
  p_valid_until timestamptz default null,p_visibility text default 'PUBLIC',
  p_supersedes_claim_id uuid default null,p_idempotency_key text default null
) returns jsonb language sql security definer set search_path='' as $$
  select world_knowledge_private.submit_authoritative_claim_v5(
    'ADMIN',p_spot_id,p_attribute_key,p_knowledge_state,p_value,p_observed_at,
    p_valid_from,p_valid_until,p_visibility,p_supersedes_claim_id,p_idempotency_key
  );
$$;

create or replace function public.world_product_owner_submit_claim_v1(
  p_spot_id uuid,p_attribute_key text,p_knowledge_state text,p_value jsonb,
  p_observed_at timestamptz,p_valid_from timestamptz default null,
  p_valid_until timestamptz default null,p_visibility text default 'PUBLIC',
  p_supersedes_claim_id uuid default null,p_idempotency_key text default null
) returns jsonb language plpgsql security definer set search_path='' as $$
begin
  if not world_knowledge_private.product_authoring_active_v1() then
    raise exception 'world_product_authoring_authority_off' using errcode='42501';
  end if;
  return world_knowledge_private.submit_authoritative_claim_v5(
    'VERIFIED_OWNER',p_spot_id,p_attribute_key,p_knowledge_state,p_value,p_observed_at,
    p_valid_from,p_valid_until,p_visibility,p_supersedes_claim_id,p_idempotency_key);
end;
$$;

create or replace function public.world_product_admin_submit_claim_v1(
  p_spot_id uuid,p_attribute_key text,p_knowledge_state text,p_value jsonb,
  p_observed_at timestamptz,p_valid_from timestamptz default null,
  p_valid_until timestamptz default null,p_visibility text default 'PUBLIC',
  p_supersedes_claim_id uuid default null,p_idempotency_key text default null
) returns jsonb language plpgsql security definer set search_path='' as $$
begin
  if not world_knowledge_private.product_admin_authoring_active_v1() then
    raise exception 'world_product_admin_authoring_off' using errcode='42501';
  end if;
  if auth.uid() is null or not public.is_admin_v1(auth.uid()) then
    raise exception 'admin_required' using errcode='42501';
  end if;
  if not exists(select 1 from public.spots s where s.id=p_spot_id and s.status='approved') then
    raise exception 'world_product_spot_not_approved' using errcode='42501';
  end if;
  return world_knowledge_private.submit_authoritative_claim_v5(
    'ADMIN',p_spot_id,p_attribute_key,p_knowledge_state,p_value,p_observed_at,
    p_valid_from,p_valid_until,p_visibility,p_supersedes_claim_id,p_idempotency_key);
end;
$$;

create or replace function public.world_shadow_rebuild_spot_v1(p_spot_id uuid,p_as_of timestamptz,p_mode text,p_idempotency_key text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  v_registry_version constant text:='backyrd.world-knowledge.registry@2.3'; v_policy_version constant text:='backyrd.world-knowledge.source-policy@4d.1';
  v_resolver_contract constant text:='backyrd.world-knowledge.shadow-resolver@1.0'; v_resolver_version constant text:='2.3.0';
  v_cutoff timestamptz; v_components jsonb; v_input_hash text; v_request_hash text; v_resolution_hash text; v_manifest_hash text;
  v_manifest_id uuid; job world_knowledge_private.rebuild_jobs%rowtype; current_pointer world_knowledge_private.current_projection_pointers%rowtype;
  snapshot jsonb; decision jsonb; stored jsonb; pointer_updated boolean:=false; manifest_reused boolean:=false;
begin
  if p_mode not in ('FULL','INCREMENTAL') or p_as_of is null or p_as_of>pg_catalog.clock_timestamp()+interval '60 seconds' or length(trim(coalesce(p_idempotency_key,''))) not between 1 and 180 then raise exception 'invalid_rebuild_request' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('world-rebuild-request:'||p_idempotency_key,0));
  -- Request identity deliberately excludes ledger state and wall-clock values. A retry
  -- binds to the original request/result even when the append-only ledger has advanced.
  v_request_hash:=encode(extensions.digest(pg_catalog.convert_to(jsonb_build_object('spotId',p_spot_id,'mode',p_mode,'asOf',p_as_of,'registryVersion',v_registry_version,'policyVersion',v_policy_version,'resolverContract',v_resolver_contract,'resolverVersion',v_resolver_version,'idempotencyIdentity',p_idempotency_key)::text,'UTF8'),'sha256'),'hex');
  select * into job from world_knowledge_private.rebuild_jobs j where j.idempotency_key=p_idempotency_key for update;
  if found then
    if job.spot_id<>p_spot_id or job.mode<>p_mode or job.as_of<>p_as_of or job.request_hash<>v_request_hash or job.registry_version<>v_registry_version or job.policy_version<>v_policy_version or job.resolver_contract<>v_resolver_contract or job.resolver_version<>v_resolver_version then raise exception 'rebuild_idempotency_conflict' using errcode='23505'; end if;
    if job.status='PENDING' then raise exception 'rebuild_request_pending' using errcode='55000'; end if;
    if job.status='RUNNING' then raise exception 'rebuild_request_in_progress' using errcode='55000'; end if;
    if job.status='FAILED' then raise exception 'rebuild_request_failed' using errcode='55000'; end if;
    if job.status<>'SUCCEEDED' or job.manifest_id is null then raise exception 'rebuild_request_invalid_state' using errcode='55000'; end if;
    if not exists(select 1 from world_knowledge_private.resolution_manifests m where m.id=job.manifest_id and m.spot_id=job.spot_id and m.registry_version=job.registry_version and m.policy_version=job.policy_version and m.resolver_contract=job.resolver_contract and m.resolver_version=job.resolver_version and m.input_hash=job.input_hash) then raise exception 'rebuild_job_manifest_binding_mismatch' using errcode='22023'; end if;
    return world_knowledge_private.validate_resolution_manifest_v1(job.manifest_id)||jsonb_build_object('mode',p_mode,'reused',true,'manifestReused',true,'pointerUpdated',false);
  end if;
  if not exists(select 1 from public.spots s where s.id=p_spot_id and s.data_origin in ('TEST','FIXTURE')) and not exists(select 1 from world_knowledge_private.shadow_spot_allowlist a where a.spot_id=p_spot_id and a.valid_until>pg_catalog.clock_timestamp()) then raise exception 'shadow_spot_not_allowlisted' using errcode='42501'; end if;
  v_cutoff:=pg_catalog.clock_timestamp();
  v_components:=world_knowledge_private.resolution_input_components_v5(p_spot_id,p_as_of,v_cutoff);
  v_input_hash:=encode(extensions.digest(pg_catalog.convert_to(v_components::text,'UTF8'),'sha256'),'hex');
  insert into world_knowledge_private.rebuild_jobs(spot_id,idempotency_key,mode,as_of,request_hash,input_hash,registry_version,policy_version,resolver_contract,resolver_version,status)
  values(p_spot_id,p_idempotency_key,p_mode,p_as_of,v_request_hash,v_input_hash,v_registry_version,v_policy_version,v_resolver_contract,v_resolver_version,'RUNNING') returning * into job;
  with eligible_pre as (
    select c.*
    from world_knowledge_private.claims c
    join world_knowledge_private.source_policy_attribute_rules policy on policy.policy_version=c.policy_version and policy.attribute_key=c.attribute_key
      and c.source_type=any(policy.allowed_source_types) and c.actor_type=any(policy.allowed_actor_types)
      and c.source_reference_id is not null and 'GENERAL_WORLD'=any(policy.allowed_use_cases)
    where c.spot_id=p_spot_id and c.created_at<=v_cutoff and c.observed_at<=p_as_of and c.visibility<>'SHADOW_HELD' and (c.valid_from is null or c.valid_from<=p_as_of) and (c.valid_until is null or c.valid_until>p_as_of)
      and exists(select 1 from world_knowledge_private.verification_records v where v.claim_id=c.id and v.claim_hash=c.content_hash and v.result='VERIFIED' and v.created_at<=v_cutoff and v.checked_at<=p_as_of and ((v.verification_method='OWNER_CONFIRMED' and 'process:owner-confirmed'=any(policy.verification_process_ids)) or (v.verification_method='ADMIN_CONFIRMED' and 'process:admin-confirmed'=any(policy.verification_process_ids))))
  ), eligible as (
    select c.*
    from eligible_pre c
    where not exists(select 1 from eligible_pre successor where successor.supersedes_claim_id=c.id)
  ), ranked as (
    select c.*,row_number() over(partition by c.attribute_key,c.scope order by c.last_changed_at desc,c.id desc) rn,
      count(*) over(partition by c.attribute_key,c.scope,c.last_changed_at) same_time
    from eligible c
  ), conflict_stats as (
    select c.attribute_key,c.scope,
      count(distinct c.knowledge_state||':'||coalesce(c.value::text,'null')) as distinct_values,
      array_agg(c.content_hash order by c.content_hash) as all_basis_hashes
    from eligible c
    group by c.attribute_key,c.scope
  ), resolved as (
    select e.attribute_key,e.scope,
      case when (e.attribute_key in ('purpose.primary_visit','offering.onsite','context.visit_situations','context.atmosphere','context.typical_dayparts') and s.distinct_values>1) or e.same_time>1 then 'DISPUTED' else e.knowledge_state end resolution,
      case when (e.attribute_key in ('purpose.primary_visit','offering.onsite','context.visit_situations','context.atmosphere','context.typical_dayparts') and s.distinct_values>1) or e.same_time>1 then null else e.value end value,
      case when (e.attribute_key in ('purpose.primary_visit','offering.onsite','context.visit_situations','context.atmosphere','context.typical_dayparts') and s.distinct_values>1) or e.same_time>1 then 'CONFLICTING' else 'VERIFIED' end trust,
      'CURRENT' freshness,
      case when e.attribute_key in ('purpose.primary_visit','offering.onsite','context.visit_situations','context.atmosphere','context.typical_dayparts') and s.distinct_values>1 then s.all_basis_hashes else array(select e2.content_hash from ranked e2 where e2.attribute_key=e.attribute_key and e2.scope=e.scope and e2.last_changed_at=e.last_changed_at order by e2.content_hash) end basis_hashes,
      e.same_time
    from ranked e join conflict_stats s using(attribute_key,scope) where e.rn=1
  )
  select jsonb_build_object(
    'contractVersion','backyrd.world-knowledge.shadow-snapshot@1.0','registryVersion',v_registry_version,'registryHash',v_components#>>'{registry,registryHash}','policyVersion',v_policy_version,'spotId',p_spot_id,'resolvedAt',p_as_of,
    'facts',coalesce(jsonb_agg(jsonb_build_object('key',attribute_key,'scope',scope,'resolution',resolution,'value',value,'trust',trust,'freshness',freshness,'basisClaimHashes',basis_hashes) order by attribute_key,scope),'[]'::jsonb),
    'explicitUnknowns',coalesce(jsonb_agg(jsonb_build_object('key',attribute_key,'scope',scope) order by attribute_key,scope) filter(where resolution='UNKNOWN'),'[]'::jsonb),
    'conflicts',coalesce(jsonb_agg(jsonb_build_object('key',attribute_key,'scope',scope,'claimHashes',basis_hashes) order by attribute_key,scope) filter(where resolution='DISPUTED'),'[]'::jsonb)
  ) into snapshot from resolved;
  decision:=world_knowledge_private.decision_projection_v1(snapshot);
  v_resolution_hash:=encode(extensions.digest(pg_catalog.convert_to(jsonb_build_object('worldSnapshot',snapshot,'decisionProjection',decision)::text,'UTF8'),'sha256'),'hex');
  -- A second, semantic lock is scoped to Spot + accepted versions + complete input.
  -- Different idempotency keys for the same resolver input therefore converge on one
  -- canonical manifest without serializing unrelated Spots or inputs.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('world-rebuild-manifest:'||p_spot_id::text||':'||v_registry_version||':'||v_policy_version||':'||v_resolver_contract||':'||v_resolver_version||':'||v_input_hash,0));
  select m.id into v_manifest_id from world_knowledge_private.resolution_manifests m where m.spot_id=p_spot_id and m.registry_version=v_registry_version and m.policy_version=v_policy_version and m.resolver_contract=v_resolver_contract and m.resolver_version=v_resolver_version and m.input_hash=v_input_hash;
  if found then
    manifest_reused:=true;
    stored:=world_knowledge_private.validate_resolution_manifest_v1(v_manifest_id);
    if stored->'worldSnapshot'<>snapshot or stored->'decisionProjection'<>decision or stored->>'resolutionHash'<>v_resolution_hash then raise exception 'resolution_manifest_reuse_mismatch' using errcode='22023'; end if;
  else
    v_manifest_hash:=encode(extensions.digest(pg_catalog.convert_to(jsonb_build_object(
      'spotId',p_spot_id,'registryVersion',v_registry_version,'registryReleaseHash',v_components#>>'{registry,releaseHash}',
      'policyVersion',v_policy_version,'policyReleaseHash',v_components#>>'{sourcePolicy,releaseHash}','attributePolicyHash',v_components#>>'{sourcePolicy,attributePolicyHash}',
      'resolverContract',v_resolver_contract,'resolverVersion',v_resolver_version,'conflictPolicyRef',v_components->>'conflictPolicyRef',
      'freshnessPolicyRef',v_components->>'freshnessPolicyRef','shadowPolicyRef',v_components->>'shadowPolicyRef','asOf',p_as_of,
      'ledgerCutoffAt',v_cutoff,'inputHash',v_input_hash,'resolutionHash',v_resolution_hash
    )::text,'UTF8'),'sha256'),'hex');
    insert into world_knowledge_private.resolution_manifests(spot_id,registry_version,policy_version,registry_release_hash,policy_release_hash,attribute_policy_hash,resolver_contract,resolver_version,conflict_policy_ref,freshness_policy_ref,shadow_policy_ref,as_of,ledger_cutoff_at,input_components,input_hash,resolution_hash,manifest_hash,world_snapshot,decision_projection)
    values(p_spot_id,v_registry_version,v_policy_version,v_components#>>'{registry,releaseHash}',v_components#>>'{sourcePolicy,releaseHash}',v_components#>>'{sourcePolicy,attributePolicyHash}',v_resolver_contract,v_resolver_version,v_components->>'conflictPolicyRef',v_components->>'freshnessPolicyRef',v_components->>'shadowPolicyRef',p_as_of,v_cutoff,v_components,v_input_hash,v_resolution_hash,v_manifest_hash,snapshot,decision) returning id into v_manifest_id;
    insert into world_knowledge_private.resolution_entries(manifest_id,attribute_key,scope,resolution,value,trust,freshness,basis_claim_hashes,conflict_claim_hashes,entry_hash)
    select v_manifest_id,item->>'key',item->>'scope',item->>'resolution',item->'value',item->>'trust',item->>'freshness',array(select jsonb_array_elements_text(item->'basisClaimHashes')),case when item->>'resolution'='DISPUTED' then array(select jsonb_array_elements_text(item->'basisClaimHashes')) else '{}' end,encode(extensions.digest(pg_catalog.convert_to(item::text,'UTF8'),'sha256'),'hex') from jsonb_array_elements(snapshot->'facts') item;
    stored:=world_knowledge_private.validate_resolution_manifest_v1(v_manifest_id);
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('world-current-pointer:'||p_spot_id::text,0));
  select * into current_pointer from world_knowledge_private.current_projection_pointers p where p.spot_id=p_spot_id for update;
  if not found then
    insert into world_knowledge_private.current_projection_pointers(spot_id,manifest_id,manifest_hash,as_of,ledger_cutoff_at,registry_version,policy_version,resolver_version) select m.spot_id,m.id,m.manifest_hash,m.as_of,m.ledger_cutoff_at,m.registry_version,m.policy_version,m.resolver_version from world_knowledge_private.resolution_manifests m where m.id=v_manifest_id;
    pointer_updated:=true;
  elsif current_pointer.manifest_id<>v_manifest_id then
    if (current_pointer.registry_version<>v_registry_version or current_pointer.policy_version<>v_policy_version or current_pointer.resolver_version<>v_resolver_version)
       and not (current_pointer.registry_version in ('backyrd.world-knowledge.registry@1.1','backyrd.world-knowledge.registry@2.0','backyrd.world-knowledge.registry@2.1') and v_registry_version='backyrd.world-knowledge.registry@2.3' and v_policy_version='backyrd.world-knowledge.source-policy@4d.1' and v_resolver_version='2.3.0')
    then raise exception 'current_projection_version_order_not_configured' using errcode='22023'; end if;
    if (current_pointer.registry_version in ('backyrd.world-knowledge.registry@1.1','backyrd.world-knowledge.registry@2.0','backyrd.world-knowledge.registry@2.1') and v_registry_version='backyrd.world-knowledge.registry@2.3')
       or p_as_of>current_pointer.as_of
       or (p_as_of=current_pointer.as_of and (select m.ledger_cutoff_at from world_knowledge_private.resolution_manifests m where m.id=v_manifest_id)>current_pointer.ledger_cutoff_at) then
      update world_knowledge_private.current_projection_pointers p set manifest_id=m.id,manifest_hash=m.manifest_hash,as_of=m.as_of,ledger_cutoff_at=m.ledger_cutoff_at,registry_version=m.registry_version,policy_version=m.policy_version,resolver_version=m.resolver_version,updated_at=pg_catalog.clock_timestamp() from world_knowledge_private.resolution_manifests m where p.spot_id=p_spot_id and m.id=v_manifest_id;
      pointer_updated:=true;
    end if;
  end if;
  update world_knowledge_private.rebuild_jobs set status='SUCCEEDED',completed_at=pg_catalog.clock_timestamp(),manifest_id=v_manifest_id where id=job.id;
  return stored||jsonb_build_object('mode',p_mode,'reused',false,'manifestReused',manifest_reused,'pointerUpdated',pointer_updated);
end $$;

create or replace function world_knowledge_private.validate_resolution_manifest_v1(p_manifest_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare m world_knowledge_private.resolution_manifests%rowtype; expected_components jsonb; expected_input_hash text; expected_resolution_hash text; expected_manifest_hash text; expected_decision jsonb; entry_facts jsonb; entry_unknowns jsonb; entry_conflicts jsonb; entries_valid boolean;
begin
  select * into strict m from world_knowledge_private.resolution_manifests where id=p_manifest_id;
  expected_components:=case
    when m.registry_version='backyrd.world-knowledge.registry@2.3' then world_knowledge_private.resolution_input_components_v5(m.spot_id,m.as_of,m.ledger_cutoff_at)
    when m.registry_version='backyrd.world-knowledge.registry@2.2' then world_knowledge_private.resolution_input_components_v4(m.spot_id,m.as_of,m.ledger_cutoff_at)
    when m.registry_version='backyrd.world-knowledge.registry@2.1' then world_knowledge_private.resolution_input_components_v3(m.spot_id,m.as_of,m.ledger_cutoff_at)
    when m.registry_version='backyrd.world-knowledge.registry@2.0' then world_knowledge_private.resolution_input_components_v2(m.spot_id,m.as_of,m.ledger_cutoff_at)
    else world_knowledge_private.resolution_input_components_v1(m.spot_id,m.as_of,m.ledger_cutoff_at)
  end;
  expected_input_hash:=encode(extensions.digest(pg_catalog.convert_to(m.input_components::text,'UTF8'),'sha256'),'hex');
  if m.input_components<>expected_components or m.input_hash<>expected_input_hash then raise exception 'resolution_manifest_input_integrity_mismatch' using errcode='22023'; end if;
  expected_decision:=world_knowledge_private.decision_projection_v1(m.world_snapshot);
  if m.decision_projection<>expected_decision then raise exception 'resolution_manifest_decision_integrity_mismatch' using errcode='22023'; end if;
  expected_resolution_hash:=encode(extensions.digest(pg_catalog.convert_to(jsonb_build_object('worldSnapshot',m.world_snapshot,'decisionProjection',m.decision_projection)::text,'UTF8'),'sha256'),'hex');
  if m.resolution_hash<>expected_resolution_hash then raise exception 'resolution_manifest_output_integrity_mismatch' using errcode='22023'; end if;
  expected_manifest_hash:=encode(extensions.digest(pg_catalog.convert_to(jsonb_build_object(
    'spotId',m.spot_id,'registryVersion',m.registry_version,'registryReleaseHash',m.registry_release_hash,
    'policyVersion',m.policy_version,'policyReleaseHash',m.policy_release_hash,'attributePolicyHash',m.attribute_policy_hash,
    'resolverContract',m.resolver_contract,'resolverVersion',m.resolver_version,'conflictPolicyRef',m.conflict_policy_ref,
    'freshnessPolicyRef',m.freshness_policy_ref,'shadowPolicyRef',m.shadow_policy_ref,'asOf',m.as_of,
    'ledgerCutoffAt',m.ledger_cutoff_at,'inputHash',m.input_hash,'resolutionHash',m.resolution_hash
  )::text,'UTF8'),'sha256'),'hex');
  if m.manifest_hash<>expected_manifest_hash then raise exception 'resolution_manifest_identity_mismatch' using errcode='22023'; end if;
  select coalesce(jsonb_agg(f.fact order by f.fact->>'key',f.fact->>'scope'),'[]'::jsonb),
         coalesce(jsonb_agg(jsonb_build_object('key',e.attribute_key,'scope',e.scope) order by e.attribute_key,e.scope) filter(where e.resolution='UNKNOWN'),'[]'::jsonb),
         coalesce(jsonb_agg(jsonb_build_object('key',e.attribute_key,'scope',e.scope,'claimHashes',to_jsonb(e.conflict_claim_hashes)) order by e.attribute_key,e.scope) filter(where e.resolution='DISPUTED'),'[]'::jsonb),
         coalesce(bool_and(e.entry_hash=encode(extensions.digest(pg_catalog.convert_to(f.fact::text,'UTF8'),'sha256'),'hex')),true)
    into entry_facts,entry_unknowns,entry_conflicts,entries_valid
  from world_knowledge_private.resolution_entries e
  cross join lateral (select jsonb_build_object('key',e.attribute_key,'scope',e.scope,'resolution',e.resolution,'value',e.value,'trust',e.trust,'freshness',e.freshness,'basisClaimHashes',to_jsonb(e.basis_claim_hashes)) as fact) f
  where e.manifest_id=m.id;
  if not entries_valid or m.world_snapshot->'facts'<>entry_facts or m.world_snapshot->'explicitUnknowns'<>entry_unknowns or m.world_snapshot->'conflicts'<>entry_conflicts then raise exception 'resolution_manifest_entries_integrity_mismatch' using errcode='22023'; end if;
  if m.world_snapshot->>'spotId'<>m.spot_id::text or m.world_snapshot->>'resolvedAt'<>to_jsonb(m.as_of)#>>'{}' or m.world_snapshot->>'registryVersion'<>m.registry_version or m.world_snapshot->>'policyVersion'<>m.policy_version then raise exception 'resolution_manifest_snapshot_binding_mismatch' using errcode='22023'; end if;
  return jsonb_build_object('manifestId',m.id,'manifestHash',m.manifest_hash,'resolutionHash',m.resolution_hash,'inputHash',m.input_hash,'worldSnapshot',m.world_snapshot,'decisionProjection',m.decision_projection);
exception when no_data_found then raise exception 'resolution_manifest_not_found' using errcode='22023';
end $$;

create or replace function world_knowledge_private.product_decision_projection_v1(p_snapshot jsonb)
returns jsonb language sql stable security definer set search_path='' as $$
  with base as (
    select world_knowledge_private.decision_projection_v1(p_snapshot) as body
  ), assembled as (
    select item from base, jsonb_array_elements(base.body->'facts') item
      where item->>'key' not like 'contact.%' and item->>'key' not in ('description.highlight','description.discovery_source','discovery.profile','operation.payment_methods')
    union all
    select item from jsonb_array_elements(coalesce(p_snapshot->'facts','[]'::jsonb)) item
      where item->>'key'=any(array['purpose.primary_visit','offering.onsite',
        'context.visit_situations','context.atmosphere','context.typical_dayparts','operation.price_options','discovery.profile'])
  ), facts as (
    select case when a.item->>'key'='state.current' then a.item||jsonb_build_object(
      'validFrom',c.valid_from,'validUntil',c.valid_until,'validityVerified',c.id is not null)
      else a.item end || case when a.item->>'key' in ('context.atmosphere','discovery.profile') then jsonb_build_object('hardConstraintAuthorized',(select count(*)=jsonb_array_length(a.item->'basisClaimHashes') and coalesce(bool_and(coalesce('HARD_CONSTRAINTS'=any(rule.allowed_use_cases),false)),false) from jsonb_array_elements_text(a.item->'basisClaimHashes') basis left join world_knowledge_private.claims claim on claim.content_hash=basis.value and claim.spot_id=(p_snapshot->>'spotId')::uuid left join world_knowledge_private.source_policy_attribute_rules rule on rule.policy_version=claim.policy_version and rule.attribute_key=claim.attribute_key)) else '{}'::jsonb end || case when a.item->>'key' in ('context.atmosphere','operation.price_options','operation.price_range','discovery.profile') then (select jsonb_build_object('validityVerified',count(claim.id)=jsonb_array_length(a.item->'basisClaimHashes'),'validFrom',max(claim.valid_from),'validUntil',min(claim.valid_until)) from jsonb_array_elements_text(a.item->'basisClaimHashes') basis left join world_knowledge_private.claims claim on claim.content_hash=basis.value and claim.spot_id=(p_snapshot->>'spotId')::uuid) else '{}'::jsonb end as item
    from assembled a
    left join world_knowledge_private.claims c
      on a.item->>'key'='state.current'
     and c.spot_id=(p_snapshot->>'spotId')::uuid
     and c.content_hash=a.item->'basisClaimHashes'->>0
    where a.item->>'key'<>'discovery.profile' or exists(
      select 1 from (select * from world_knowledge_private.claims where spot_id=(p_snapshot->>'spotId')::uuid and attribute_key='description.discovery_source' and visibility<>'SHADOW_HELD' order by last_changed_at desc,id desc limit 1) source
      where source.visibility='PUBLIC' and source.knowledge_state='KNOWN_VALUE' and source.value=to_jsonb(a.item->'value'->>'description') and source.stance='SUPPORTS'
    )
  ), unknowns as (
    select item from base,jsonb_array_elements(base.body->'explicitUnknowns') item
      where item->>'key' not like 'contact.%' and item->>'key' not in ('description.highlight','description.discovery_source','discovery.profile','operation.payment_methods')
    union all
    select item from jsonb_array_elements(coalesce(p_snapshot->'explicitUnknowns','[]'::jsonb)) item
      where item->>'key'=any(array['purpose.primary_visit','offering.onsite',
        'context.visit_situations','context.atmosphere','context.typical_dayparts','operation.price_options','discovery.profile'])
  ), conflicts as (
    select item from base,jsonb_array_elements(base.body->'conflicts') item
      where item->>'key' not like 'contact.%' and item->>'key' not in ('description.highlight','description.discovery_source','discovery.profile','operation.payment_methods')
    union all
    select item from jsonb_array_elements(coalesce(p_snapshot->'conflicts','[]'::jsonb)) item
      where item->>'key'=any(array['purpose.primary_visit','offering.onsite',
        'context.visit_situations','context.atmosphere','context.typical_dayparts','operation.price_options','discovery.profile'])
  )
  select jsonb_build_object(
    'contractVersion','backyrd.world-knowledge.product-decision-projection@1.0',
    'spotId',p_snapshot->>'spotId','registryVersion',p_snapshot->>'registryVersion',
    'policyVersion',p_snapshot->>'policyVersion',
    'facts',coalesce((select jsonb_agg(item order by item->>'key',item->>'scope') from facts),'[]'::jsonb),
    'explicitUnknowns',coalesce((select jsonb_agg(item order by item->>'key',item->>'scope') from unknowns),'[]'::jsonb),
    'conflicts',coalesce((select jsonb_agg(item order by item->>'key',item->>'scope') from conflicts),'[]'::jsonb)
  );
$$;

create or replace function public.backyrd_decision_vnext_product_context_v5(
  p_auth_user_id uuid,p_subject_binding_hash text,p_target_city text,p_primary_intent text,
  p_release_hash text,p_artifact_hash text,p_source_set_hash text,p_generation bigint
) returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare v_context jsonb; v_world jsonb; v_count integer;
begin
  perform decision_vnext_private.assert_service_authority_v1();
  v_context := public.backyrd_decision_vnext_product_context_v4(
    p_auth_user_id,p_subject_binding_hash,p_target_city,
    case when p_primary_intent='NIGHTLIFE' then 'DRINKS' else p_primary_intent end,
    p_release_hash,p_artifact_hash,p_source_set_hash,p_generation
  );
  with verified as materialized (
    select s.id spot_id,m.manifest_hash,m.world_snapshot
    from public.spots s
    join world_knowledge_private.current_projection_pointers p on p.spot_id=s.id
    join world_knowledge_private.resolution_manifests m on m.id=p.manifest_id and m.manifest_hash=p.manifest_hash
    where s.status='approved'
      and ((m.registry_version='backyrd.world-knowledge.registry@2.1' and m.policy_version='backyrd.world-knowledge.source-policy@4b.1') or (m.registry_version='backyrd.world-knowledge.registry@2.3' and m.policy_version='backyrd.world-knowledge.source-policy@4d.1'))
      and (world_knowledge_private.validate_resolution_manifest_v1(m.id)->>'manifestHash')=m.manifest_hash
      and exists (
        select 1 from jsonb_array_elements(coalesce(m.world_snapshot->'facts','[]'::jsonb)) f
        where f->>'key'='location.locality' and f->>'resolution'='KNOWN_VALUE'
          and f->>'trust'='VERIFIED' and f->>'freshness'='CURRENT'
          and lower(translate(f->>'value','äöüÄÖÜ','aouAOU'))=
              lower(translate(btrim(p_target_city),'äöüÄÖÜ','aouAOU'))
      )
      and exists (
        select 1 from jsonb_array_elements(coalesce(m.world_snapshot->'facts','[]'::jsonb)) f
        where f->>'key'='identity.name' and f->>'resolution'='KNOWN_VALUE'
          and f->>'trust'='VERIFIED' and f->>'freshness'='CURRENT'
          and nullif(btrim(f->>'value'),'') is not null
      )
      and not exists (
        select 1 from jsonb_array_elements(coalesce(m.world_snapshot->'conflicts','[]'::jsonb)) conflict
        where conflict->>'key'='location.locality'
      )
    order by s.id
    limit 1001
  )
  select count(*),coalesce(jsonb_agg(jsonb_build_object(
    'contractVersion','backyrd.world-knowledge.product-resolver-binding@1.0',
    'manifestHash',v.manifest_hash,'registryHash',v.world_snapshot->>'registryHash',
    'resolvedAt',v.world_snapshot->>'resolvedAt',
    'decisionProjection',world_knowledge_private.product_decision_projection_v1(v.world_snapshot)
  ) order by v.spot_id),'[]'::jsonb) into v_count,v_world from verified v;
  if v_count=0 or v_count>1000 then
    raise exception 'decision_vnext_product_world_cohort_unavailable' using errcode='55000';
  end if;
  return v_context||jsonb_build_object('worldSnapshots',v_world);
end;
$$;

create or replace function public.world_authoring_submit_taxonomy_candidate_v1(
  p_spot_id uuid,
  p_attribute_key text,
  p_primary_category text,
  p_candidate_value jsonb,
  p_taxonomy_version text,
  p_idempotency_key text
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
  actor_id uuid:=auth.uid(); access jsonb; binding_id uuid; existing world_knowledge_private.authoring_taxonomy_candidates_v2%rowtype;
  current_category text; candidate_hash text;
begin
  access:=world_knowledge_private.authoring_actor_v1(p_spot_id);
  if actor_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_attribute_key not in ('classification.place_types','offering.cuisines','offering.food_specialities','offering.groups','amenity.features')
     or p_taxonomy_version not in ('backyrd.world-knowledge.authoring-taxonomy@4a.2','backyrd.world-knowledge.authoring-taxonomy@4c.1')
  then raise exception 'taxonomy_candidate_contract_mismatch' using errcode='22023'; end if;
  if not (access->'allowedAttributeKeys') @> to_jsonb(array[p_attribute_key]) then raise exception 'attribute_entitlement_denied' using errcode='42501'; end if;
  select c.value#>>'{}' into current_category from world_knowledge_private.claims c where c.spot_id=p_spot_id and c.attribute_key='classification.primary_category' and c.knowledge_state='KNOWN_VALUE' order by c.last_changed_at desc,c.id desc limit 1;
  if current_category is distinct from p_primary_category then raise exception 'taxonomy_candidate_category_conflict' using errcode='22023'; end if;
  if not world_knowledge_private.authoring_taxonomy_candidate_allowed_v1(p_attribute_key,p_primary_category,p_candidate_value) then raise exception 'invalid_taxonomy_candidate' using errcode='22023'; end if;
  if length(trim(coalesce(p_idempotency_key,''))) not between 1 and 180 then raise exception 'invalid_idempotency_key' using errcode='22023'; end if;
  binding_id:=world_knowledge_private.get_actor_binding_v1(actor_id,access->>'role');
  candidate_hash:=encode(extensions.digest(pg_catalog.convert_to(jsonb_build_object('spotId',p_spot_id,'attributeKey',p_attribute_key,'primaryCategory',p_primary_category,'candidateValue',p_candidate_value,'taxonomyVersion',p_taxonomy_version,'actorBinding',binding_id,'idempotencyIdentity',p_idempotency_key)::text,'UTF8'),'sha256'),'hex');
  select * into existing from world_knowledge_private.authoring_taxonomy_candidates_v2 c where c.actor_binding_id=binding_id and c.idempotency_key=p_idempotency_key;
  if found then
    if existing.candidate_hash<>candidate_hash then raise exception 'taxonomy_candidate_idempotency_conflict' using errcode='23505'; end if;
    return jsonb_build_object('candidateId',existing.id,'created',false,'candidateHash',existing.candidate_hash,'engineAuthorized',false);
  end if;
  insert into world_knowledge_private.authoring_taxonomy_candidates_v2(spot_id,attribute_key,primary_category,candidate_value,taxonomy_version,actor_binding_id,idempotency_key,candidate_hash)
  values(p_spot_id,p_attribute_key,p_primary_category,p_candidate_value,p_taxonomy_version,binding_id,p_idempotency_key,candidate_hash) returning * into existing;
  return jsonb_build_object('candidateId',existing.id,'created',true,'candidateHash',existing.candidate_hash,'engineAuthorized',false);
end $$;

revoke all on function world_knowledge_private.submit_authoritative_claim_v5(text,uuid,text,text,jsonb,timestamptz,timestamptz,timestamptz,text,uuid,text) from public,anon,authenticated,service_role;

revoke all on function world_knowledge_private.resolution_input_components_v5(uuid,timestamptz,timestamptz) from public,anon,authenticated,service_role;

create or replace function public.world_product_authoring_detail_v1(p_spot_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_actor uuid:=auth.uid(); v_role text; v_entitlement text;
  v_allowed jsonb; v_result jsonb;
begin
  if v_actor is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if public.is_admin_v1(v_actor) then v_role:='ADMIN'; v_entitlement:='ADMIN';
  elsif exists(select 1 from public.spots s where s.id=p_spot_id and s.owner_id=v_actor) then
    v_role:='VERIFIED_OWNER';
    v_entitlement:=case when exists(
      select 1 from public.backyrd_spot_owner_intelligence_entitlements_v1 e
      where e.spot_id=p_spot_id and e.owner_id=v_actor and e.tier='PREMIUM'
        and e.valid_from<=pg_catalog.clock_timestamp()
        and (e.valid_until is null or e.valid_until>pg_catalog.clock_timestamp())
    ) then 'OWNER_PRO' else 'OWNER_BASIC' end;
  else raise exception 'world_authoring_scope_denied' using errcode='42501'; end if;
  select coalesce(jsonb_agg(r.attribute_key order by r.attribute_key),'[]'::jsonb)
    into v_allowed from world_knowledge_private.entitlement_attribute_rules r
    where r.policy_version='backyrd.world-knowledge.entitlement-policy@4d.1'
      and r.actor_scope=v_entitlement;
  select jsonb_build_object(
    'contractVersion','backyrd.world-knowledge.product-authoring-detail@1.0',
    'spotId',s.id,'name',s.name,'status',s.status,
    'actor',jsonb_build_object('role',v_role,'entitlement',v_entitlement,'allowedAttributeKeys',v_allowed),
    'answers',coalesce((select jsonb_object_agg(attribute_key,answer) from (
      select distinct on (c.attribute_key) c.attribute_key,
        jsonb_build_object('claimId',c.id,'knowledgeState',c.knowledge_state,'value',c.value,
          'validUntil',c.valid_until,'visibility',c.visibility) answer
      from world_knowledge_private.claims c where c.spot_id=p_spot_id
        and (v_role='ADMIN' or (c.visibility='PUBLIC' and c.attribute_key in (
          select r.attribute_key from world_knowledge_private.entitlement_attribute_rules r
          where r.policy_version='backyrd.world-knowledge.entitlement-policy@4d.1'
            and r.actor_scope=v_entitlement)))
      order by c.attribute_key,c.last_changed_at desc,c.id desc
    ) latest),'{}'::jsonb),
    'openConflicts',coalesce((select jsonb_agg(jsonb_build_object('class',w.work_class,'attributeKey',w.attribute_key,'reasonCodes',to_jsonb(w.reason_codes)))
      from world_knowledge_private.review_work_items w
      where w.spot_id=p_spot_id and w.status in ('OPEN','IN_REVIEW')),'[]'::jsonb),
    'manifest',case when m.id is null then null else jsonb_build_object(
      'manifestHash',m.manifest_hash,'worldSnapshot',m.world_snapshot) end
  ) into v_result from public.spots s
    left join world_knowledge_private.current_projection_pointers p on p.spot_id=s.id
    left join world_knowledge_private.resolution_manifests m on m.id=p.manifest_id
    where s.id=p_spot_id and s.status='approved';
  if v_result is null then raise exception 'world_product_spot_not_approved' using errcode='42501'; end if;
  return v_result;
end;
$$;

-- Public import sources use the existing append-only authoritative claim ledger.
-- The browser cannot forward arbitrary/private text to the provider endpoint.
create function public.world_product_discovery_publish_source_v1(p_spot_id uuid,p_source_text text,p_idempotency_key text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare detail jsonb; result jsonb; prior_id uuid; actor_binding uuid; prior_request world_knowledge_private.claims%rowtype;
begin
 if not world_knowledge_private.product_authoring_active_v1() then raise exception 'world_product_authoring_authority_off' using errcode='42501'; end if;
 detail:=public.world_product_authoring_detail_v1(p_spot_id);
 if not(detail->'actor'->'allowedAttributeKeys' ? 'description.discovery_source') then raise exception 'attribute_entitlement_denied' using errcode='42501'; end if;
 if length(trim(coalesce(p_source_text,''))) not between 1 and 12000 then raise exception 'source_size_invalid' using errcode='22023'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('discovery-source:'||auth.uid()::text,0));
 actor_binding:=world_knowledge_private.get_actor_binding_v1(auth.uid(),detail->'actor'->>'role');
 select * into prior_request from world_knowledge_private.claims where actor_binding_id=actor_binding and idempotency_key=p_idempotency_key;
 if found then
  if prior_request.spot_id<>p_spot_id or prior_request.attribute_key<>'description.discovery_source' or prior_request.value<>to_jsonb(p_source_text) or prior_request.visibility not in ('PUBLIC','SHADOW_HELD') then raise exception 'claim_idempotency_conflict' using errcode='23505';end if;
  return jsonb_build_object('claimId',prior_request.id,'created',false,'visibility',prior_request.visibility,'sourceHash',encode(extensions.digest(pg_catalog.convert_to(p_source_text,'UTF8'),'sha256'),'hex'));
 end if;
 select id into prior_id from world_knowledge_private.claims where spot_id=p_spot_id and attribute_key='description.discovery_source' order by last_changed_at desc,id desc limit 1;
 result:=world_knowledge_private.submit_authoritative_claim_v5(detail->'actor'->>'role',p_spot_id,'description.discovery_source','KNOWN_VALUE',to_jsonb(p_source_text),pg_catalog.clock_timestamp(),null,null,'PUBLIC',prior_id,p_idempotency_key);
 return result||jsonb_build_object('sourceHash',encode(extensions.digest(pg_catalog.convert_to(p_source_text,'UTF8'),'sha256'),'hex'));
end $$;
revoke all on function public.world_product_discovery_publish_source_v1(uuid,text,text) from public,anon,service_role;
grant execute on function public.world_product_discovery_publish_source_v1(uuid,text,text) to authenticated;

create table world_knowledge_private.discovery_preparation_budgets(actor_id uuid not null,period text not null,used integer not null check(used>=0),primary key(actor_id,period));
alter table world_knowledge_private.discovery_preparation_budgets enable row level security;
revoke all on world_knowledge_private.discovery_preparation_budgets from public,anon,authenticated,service_role;

create function public.world_product_discovery_prepare_context_v1(p_spot_id uuid,p_source_hash text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); detail jsonb; source world_knowledge_private.claims%rowtype; digest text; minute_key text; day_key text; used_count integer;
begin
 if actor is null or not world_knowledge_private.product_authoring_active_v1() then raise exception 'world_product_authoring_authority_off' using errcode='42501'; end if;
 detail:=public.world_product_authoring_detail_v1(p_spot_id);
 if not(detail->'actor'->'allowedAttributeKeys' ? 'discovery.profile') then raise exception 'attribute_entitlement_denied' using errcode='42501'; end if;
 select * into source from world_knowledge_private.claims where spot_id=p_spot_id and attribute_key='description.discovery_source' order by last_changed_at desc,id desc limit 1;
 if not found or source.visibility<>'PUBLIC' or source.knowledge_state<>'KNOWN_VALUE' or jsonb_typeof(source.value)<>'string' or source.stance<>'SUPPORTS' or source.source_type not in ('OWNER_ASSERTION','ADMIN_OBSERVATION','OFFICIAL_SOURCE') or source.valid_from>pg_catalog.clock_timestamp() or source.valid_until<=pg_catalog.clock_timestamp()
 or coalesce((select v.result='VERIFIED' from world_knowledge_private.verification_records v where v.claim_id=source.id and v.claim_hash=source.content_hash order by v.checked_at desc,v.created_at desc,v.id desc limit 1),false)=false then raise exception 'confirmed_public_source_required' using errcode='42501'; end if;
 digest:=encode(extensions.digest(pg_catalog.convert_to(source.value#>>'{}','UTF8'),'sha256'),'hex');
 if p_source_hash is null or digest<>p_source_hash then raise exception 'source_changed' using errcode='22023'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('discovery-budget:'||actor::text,0));
 minute_key:=to_char(pg_catalog.clock_timestamp() at time zone 'UTC','YYYYMMDDHH24MI');day_key:=to_char(pg_catalog.clock_timestamp() at time zone 'UTC','YYYYMMDD');
 for minute_key in select unnest(array[minute_key,day_key]) loop
   insert into world_knowledge_private.discovery_preparation_budgets(actor_id,period,used) values(actor,minute_key,1) on conflict(actor_id,period) do update set used=discovery_preparation_budgets.used+1 returning used into used_count;
   if used_count>(case when length(minute_key)=8 then 100 when detail->'actor'->>'role'='ADMIN' then 50 else 10 end) then raise exception 'discovery_preparation_rate_limited' using errcode='PT429';end if;
 end loop;
 delete from world_knowledge_private.discovery_preparation_budgets where actor_id=actor and period<to_char((pg_catalog.clock_timestamp()-interval '2 days') at time zone 'UTC','YYYYMMDD');
 return jsonb_build_object('sourceText',source.value#>>'{}','sourceHash',digest,'visibility','PUBLIC');
end $$;
revoke all on function public.world_product_discovery_prepare_context_v1(uuid,text) from public,anon,service_role;
grant execute on function public.world_product_discovery_prepare_context_v1(uuid,text) to authenticated;

-- Reuse the existing text quarantine for the newly public source and profile.
-- No publication/import path may evade the canonical shadow hold.
create or replace function world_knowledge_private.text_requires_shadow_v1(p_attribute_key text,p_value jsonb)
returns boolean language sql immutable set search_path='' as $$
 select p_attribute_key in ('description.highlight','description.discovery_source','discovery.profile')
   and case when p_attribute_key='discovery.profile' then coalesce(p_value::text,'') else coalesce(p_value#>>'{}','') end ~* '(rassist|nazi|hate|hass|kill|illegal|verboten)';
$$;
